{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a mirror map in a ruined plaza.",
      "visual_description": "A cracked stone plaza filled with rubble. Mara stands over a large mirror laid flat, its surface showing a shifting map of the city. Broken columns and faded royal banners hang from tilting poles around her.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp flickers a warning about the castle gates.",
      "visual_description": "Inside a collapsed archway, the Oracle Lamp sits on a stone ledge. Its flame eye glows amber as it speaks. Beyond the arch, the massive rusted castle gates loom, half-open and tangled with thorny vines.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Glass Diver emerges from a shattered window.",
      "visual_description": "A tall broken window in a crumbling wall. The Glass Diver steps through the frame, diving helmet gleaming, coat reflecting distant fires. Shards of glass float momentarily in the air behind him.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scouts ahead past abandoned market stalls.",
      "visual_description": "A narrow street lined with overturned carts and tattered awnings. Tin Fox trots quietly, its metal paws clicking on cobblestones. Blue glass eyes scan the shadows. Tattered royal banners hang from a broken beam overhead.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The Sleeping Tax Collector dozes behind a ledger desk at a crossroads.",
      "visual_description": "A stone desk set up in the middle of a crossroads, papers and ledgers stacked high. The Sleeping Tax Collector snores softly, head resting on a paper pillow. Ink-stained stamps are stuck to his sleeves. Frightened townspeople peek from shuttered windows nearby.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara consults her compass while Tin Fox reports from a high ledge.",
      "visual_description": "A ruined bell tower with a collapsed roof. Mara stands on a broken stair, holding her brass compass. Tin Fox perches on a stone ledge above, blue eyes blinking. The Oracle Lamp rests on a fallen beam, casting a warm glow.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The Glass Diver passes through a cursed tower's mirrored door.",
      "visual_description": "A tall, spiraling stone tower with a door made entirely of black mirror. The Glass Diver places a hand on the surface, which ripples like water. His reflection stretches and distorts. Old royal banners flap from the tower's upper windows.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Inside the tower, the Oracle Lamp warns of armored patrols.",
      "visual_description": "A circular chamber with dust-covered floor tiles. The Oracle Lamp sits on a pedestal, its flame eye darting toward a stone staircase. Armored footsteps echo from above. Mara and the Glass Diver press against the wall, shadows hiding them.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox finds a hidden passage behind a faded banner.",
      "visual_description": "A narrow corridor with a large, threadbare royal banner hanging on one wall. Tin Fox nuzzles the fabric, revealing a dark opening behind it. Dust motes dance in a sliver of light from a crack above.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The Sleeping Tax Collector is dragged into the passage, still asleep.",
      "visual_description": "Mara and the Glass Diver pull the snoozing Tax Collector through the hidden opening. His ledger slides across the floor behind him. The Oracle Lamp floats in the air, lighting the way. Faint armored footsteps grow louder outside.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The group emerges into a courtyard with a magic door.",
      "visual_description": "A moonlit courtyard with a stone archway at its center. The arch holds a shimmering door of blue light, pulsing gently. Rubble and broken statues surround it. The Oracle Lamp's eye narrows as it inspects the light.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "Tin Fox triggers a trap near the magic door.",
      "visual_description": "Tin Fox steps on a loose stone. A hidden mechanism clicks, and a net of chains drops from above, barely missing the group. The Glass Diver rolls aside, coat flaring. The magic door flickers in response.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Mara deciphers a riddle on the magic door's frame.",
      "visual_description": "Mara leans close to the glowing door, tracing runes carved into the stone arch with ink-stained fingers. The Oracle Lamp hovers at her shoulder, reading the riddle aloud. Tin Fox sits alert, watching for danger.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The Glass Diver uses his helmet to reflect light through the door.",
      "visual_description": "The Glass Diver tilts his head, catching moonlight on his diving helmet. A beam of light refracts through the crystal visor and strikes the magic door, which ripples and swings open, revealing a dark stairway beyond.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols corner the group on the stairs.",
      "visual_description": "A narrow spiral staircase lit by torchlight. At the top, armored figures descend, their metal boots clanking. The group presses downward, the Sleeping Tax Collector still comatose. The Oracle Lamp dims its flame to hide them.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The Glass Diver shatters a window to create an escape route.",
      "visual_description": "At the bottom of the stairs, a large stained-glass window depicts a faded royal crest. The Glass Diver strikes it with his fist, and it explodes into a cascade of colored shards. Moonlight floods in, revealing a bridge outside.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The group flees across a crumbling bridge over a ravine.",
      "visual_description": "A narrow stone bridge spans a deep ravine, its edges crumbling. The group runs single file, the Glass Diver in the lead. The Oracle Lamp swings wildly, casting erratic shadows. Behind them, the tower's windows flicker with torchlight.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they reach safety.",
      "visual_description": "The far side of the ravine is a grassy hill. The group stands panting as the bridge crumbles into the darkness. The Glass Diver removes his helmet, breathing fresh air. The Oracle Lamp's eye glows steady. Dawn light touches the horizon.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

